/**
 * TeamBriefSection — Phase 5.2.C
 *
 * Copilot panel top section for managers: surfaces the most recent
 * auto_drive.team_tick interaction so the manager can see "AI 已替你
 * 团队整理 N 件事" without leaving the chat. One-click expansion;
 * dismissable.
 *
 * Per plan v1.2 §4.4 + §4.7 — push-driven (the data is generated by
 * the cron-fired auto_drive.run_for_team), this widget is the
 * SPA-side surface for managers who happen to be in front of the
 * computer when the brief gets ready.
 */

import React, { useEffect, useState } from "react";
import { CronHealthLine } from "@/components/CronHealthLine";
import { useT } from "@/lib/i18n";
import { fetchTeamBriefLatest, type TeamBriefTick } from "../lib/api";

interface Props {
  isManager: boolean;
}

export function TeamBriefSection({ isManager }: Props) {
  const t = useT();
  const [tick, setTick] = useState<TeamBriefTick | null>(null);
  const [dismissed, setDismissed] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!isManager) return;
    setLoading(true);
    fetchTeamBriefLatest()
      .then(({ tick }) => setTick(tick))
      .catch((e) => console.warn("team_brief_latest failed", e))
      .finally(() => setLoading(false));
  }, [isManager]);

  // Non-managers never see the brief; managers always do (presence is
  // the point). Loading is brief — render nothing rather than flash a
  // skeleton; dismiss hides it for the session.
  if (!isManager || dismissed || loading) return null;

  // No recent team_tick yet (cron hasn't produced one, or the manager
  // role just changed and the historical ticks are keyed to the prior
  // manager). Show an honest empty state instead of disappearing — the
  // silent vanish reads as "feature broken".
  if (!tick) {
    return (
      <div style={{
        background: "linear-gradient(135deg, var(--accent-soft-strong), var(--accent-soft))",
        border: "1px solid var(--accent)",
        borderRadius: 8, padding: 12, marginBottom: 12,
        fontSize: 14,
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontSize: 18 }}>🌅</span>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 600 }}>{t("team_brief.title")}</div>
            <div style={{ fontSize: 14, color: "var(--mute)", marginTop: 2 }}>
              {t("team_brief.empty")}
            </div>
          </div>
          <button
            onClick={() => setDismissed(true)}
            aria-label={t("team_brief.dismiss")}
            title={t("team_brief.dismiss")}
            style={{
              background: "transparent", border: "none",
              color: "var(--mute)", cursor: "pointer", fontSize: 14,
            }}
          >×</button>
        </div>
      </div>
    );
  }

  const c = tick.content || {};
  const memberCount = c.member_count ?? 0;
  const actionsPlanned = c.actions_planned ?? 0;
  const teamSignals = c.team_signals_count ?? 0;
  const isDryRun = !!c.dry_run;

  return (
    <div style={{
      background: "linear-gradient(135deg, var(--accent-soft-strong), var(--accent-soft))",
      border: "1px solid var(--accent)",
      borderRadius: 8, padding: 12, marginBottom: 12,
      fontSize: 14,
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <span style={{ fontSize: 18 }}>🌅</span>
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 600 }}>
            {t("team_brief.title")}
            {isDryRun && (
              <span style={{
                marginLeft: 8, padding: "2px 6px",
                background: "var(--surface-soft)", borderRadius: 4,
                fontSize: 13, color: "var(--mute)",
              }}>
                dry-run
              </span>
            )}
          </div>
          <div style={{ fontSize: 14, color: "var(--mute)", marginTop: 2 }}>
            {t("team_brief.summary", {
              members: String(memberCount),
              actions: String(actionsPlanned),
              signals: String(teamSignals),
            })}
          </div>
        </div>
        <button
          onClick={() => setExpanded((v) => !v)}
          style={{
            background: "transparent", border: "1px solid var(--border)",
            borderRadius: 4, padding: "4px 8px", fontSize: 14,
            color: "var(--text)", cursor: "pointer",
          }}
        >
          {expanded ? t("team_brief.collapse") : t("team_brief.expand")}
        </button>
        <button
          onClick={() => setDismissed(true)}
          aria-label={t("team_brief.dismiss")}
          title={t("team_brief.dismiss")}
          style={{
            background: "transparent", border: "none",
            color: "var(--mute)", cursor: "pointer", fontSize: 14,
          }}
        >×</button>
      </div>

      {expanded && (
        <div style={{ marginTop: 12, fontSize: 14, color: "var(--mute)" }}>
          <div style={{ display: "grid", gridTemplateColumns: "auto 1fr", gap: "4px 12px" }}>
            <div>{t("team_brief.generated_at")}</div>
            <div>{tick.occurred_at?.replace("T", " ").slice(0, 16) || t("team_brief.unknown_time")}</div>
            <div>{t("team_brief.actions_executed")}</div>
            <div>{c.actions_executed ?? 0}</div>
            <div>{t("team_brief.signals_seen")}</div>
            <div>{c.signals_seen ?? 0}</div>
          </div>
          <div style={{ marginTop: 8, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <CronHealthLine mode="compact" />
            <span style={{ fontSize: 13, color: "var(--mute)" }}>
              <a
                href="/app/ai-audit"
                style={{ color: "var(--accent)" }}
              >
                {t("team_brief.ai_audit_link")}
              </a>
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

export default TeamBriefSection;
